return ['domain'=>'simple-tags','plural-forms'=>'nplurals=1; plural=0;','language'=>'th','project-id-version'=>'PublishPress Taxonomies Free 3.53.0','pot-creation-date'=>'2026-09-04T13:08:23+00:00','po-revision-date'=>'2026-10-31 02:01+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Taxonomies Free'=>'PublishPress Taxonomies Free','https://wordpress.org/plugins/simple-tags/'=>'https://wordpress.org/plugins/simple-tags/','PublishPress Taxonomies allows you to create and manage Tags, Categories, and all your WordPress taxonomy terms.'=>'PublishPress Taxonomies allows you to create and manage Tags, Categories, and all your WordPress taxonomy terms.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Here'=>'ที่นี่',' Select current post'=>'เลือกโพสต์ปัจจุบัน','Current Posts (PublishPress Taxonomies)'=>'โพสต์ปัจจุบัน (PublishPress Taxonomies)','this page.'=>'หน้านี้.','Select related post'=>'เลือกโพสต์ที่เกี่ยวข้อง','Related Posts (PublishPress Taxonomies)'=>'โพสต์ที่เกี่ยวข้อง (PublishPress Taxonomies)','Select Terms Display'=>'เลือกการแสดงคำศัพท์','Terms Display (PublishPress Taxonomies)'=>'การแสดงคำศัพท์ (PublishPress Taxonomies)','Permission denied.'=>'การอนุญาตถูกปฏิเสธ.','The batch limit must be between 1 and %d posts.'=>'ขีดจำกัดของแบตช์ต้องอยู่ระหว่าง 1 ถึง %d โพสต์.','The batch wait time must be between 0 and %d seconds.'=>'เวลารอของแบตช์ต้องอยู่ระหว่าง 0 ถึง %d วินาที.','Auto Term is required, kindly add an Auto Term from Auto Term menu.'=>'ต้องมี Auto Term กรุณาเพิ่ม Auto Term จากเมนู Auto Term.','Limit per batches is required.'=>'ต้องการขีดจำกัดต่อกลุ่ม','Batches wait time is required.'=>'ต้องการเวลารอระหว่างกลุ่ม','Auto term settings not found'=>'ไม่พบการตั้งค่า Auto Term','The selected Auto Term setting is not enabled for any post type. Please select at least one post type in the Auto Term settings.'=>'การตั้งค่า Auto Term ที่เลือกไม่ได้เปิดใช้งานสำหรับโพสต์ประเภทใด ๆ กรุณาเลือกโพสต์ประเภทอย่างน้อยหนึ่งปร